namespace Nri.Server.Application;

public sealed class ServerRuntime
{
    public ServerRuntime(CommandDispatcher dispatcher, SessionManager sessions, FateEngineStateService fateState, FateEngineSettingsStore fateSettingsStore, GameContentService contentService, ICombatRuntimePersistenceService combatRuntimePersistence)
    {
        Dispatcher = dispatcher;
        Sessions = sessions;
        FateState = fateState;
        FateSettingsStore = fateSettingsStore;
        ContentService = contentService;
        CombatRuntimePersistence = combatRuntimePersistence;
    }

    public CommandDispatcher Dispatcher { get; }
    public SessionManager Sessions { get; }
    public FateEngineStateService FateState { get; }
    public FateEngineSettingsStore FateSettingsStore { get; }
    public GameContentService ContentService { get; }
    public ICombatRuntimePersistenceService CombatRuntimePersistence { get; }
}

public static class ServiceRegistry
{
