        var mongo = new MongoContext(config, logger);
        var repositories = new MongoRepositoryFactory(mongo, logger);
        var featureFlags = new RuntimeFeatureFlagProvider(
            config,
            logger,
            repositories.FeatureFlagOverrides,
            mongo.Database.GetCollection<MongoDB.Bson.BsonDocument>("feature_flag_overrides"));
        CombatFeatureGate.Configure(featureFlags);
        BootstrapAdminInitializer.Ensure(config, repositories, logger);
